/**
 * #136 — message triggers are written through POST / PATCH / DELETE
 * /api/behaviors. The final state is checked against the Message Trigger
 * rules (ADR 0003: placement only in guilds, audience only in bot DMs);
 * the webhook secret is generated by the bot, shown once, and never read
 * back; every write lands in admin_audit_log without a secret or URL.
 */
import { vi, describe, it, expect, beforeAll, beforeEach } from "vitest";

vi.hoisted(() => {
  process.env.SQLITE_DB_PATH = ":memory:";
  process.env.ENCRYPTION_KEY = "a".repeat(64);
  delete process.env.WEBHOOK_ALLOW_PRIVATE;
});

vi.mock("../src/modules/bot-events/bot-event-log.js", () => ({
  botEventLog: { record: vi.fn() },
}));

import Fastify, { type FastifyInstance } from "fastify";
import { sequelize } from "../src/db.js";
import { registerBehaviorRoutes } from "../src/modules/behavior/behavior-routes.js";
import { listAudit } from "../src/modules/admin/admin-audit.service.js";
import { decryptSecret } from "../src/utils/crypto.js";
import { clearBehaviors, seedMessageTrigger, seedSystemLogin } from "./behavior-fixtures.js";

const HOOK = "https://203.0.113.10/hook";
const GUILD = "123456789012345678";
const CHANNEL = "223456789012345678";
const USER = "323456789012345678";

const forward = vi.fn(async () => ({ ok: true, reply: {}, notes: [] }));
let server: FastifyInstance;

beforeAll(async () => {
  await sequelize.sync({ force: true });
  server = Fastify({ logger: false });
  server.addHook("onRequest", async (request) => {
    request.authUserId = "admin";
    request.authCapabilities = new Set(["behavior.manage"]) as never;
  });
  await registerBehaviorRoutes(server, { forwarder: { forward } as never });
  await server.ready();
});

beforeEach(async () => {
  await clearBehaviors();
  forward.mockClear();
});

function create(payload: Record<string, unknown>) {
  return server.inject({ method: "POST", url: "/api/behaviors", payload });
}

function patch(id: number, payload: Record<string, unknown>) {
  return server.inject({ method: "PATCH", url: `/api/behaviors/${id}`, payload });
}

const dmTrigger = {
  title: "hello",
  surface: "bot_dm",
  patternKind: "startswith",
  patternValue: "!hello",
  webhook: { url: HOOK },
};

async function listed(): Promise<Array<Record<string, unknown>>> {
  const res = await server.inject({ method: "GET", url: "/api/behaviors" });
  return res.json().messageTriggers;
}

describe("POST /api/behaviors (message trigger)", () => {
  it("creates a bot DM trigger and lists it", async () => {
    const res = await create(dmTrigger);
    expect(res.statusCode).toBe(201);
    const { behavior } = res.json();
    expect(behavior).toMatchObject({
      kind: "message",
      title: "hello",
      enabled: true,
      surface: "bot_dm",
      guildId: null,
      channelId: null,
      patternKind: "startswith",
      patternValue: "!hello",
      stopOnMatch: false,
      audienceKind: "all",
      section: "bot_dm",
      webhook: { url: HOOK, authMode: null, secretSet: false, previousSecretExpiresAt: null },
    });
    expect(res.json()).not.toHaveProperty("secret");
    expect((await listed()).map((t) => t.id)).toEqual([behavior.id]);
  });

  it("creates a channel trigger in its channel section", async () => {
    const res = await create({
      ...dmTrigger,
      surface: "guild",
      guildId: GUILD,
      channelId: CHANNEL,
      ignoreBots: false,
    });
    expect(res.statusCode).toBe(201);
    expect(res.json().behavior).toMatchObject({
      section: `channel:${GUILD}:${CHANNEL}`,
      ignoreBots: false,
    });
  });

  it("issues the webhook secret once and only reports secretSet afterwards", async () => {
    const res = await create({ ...dmTrigger, webhook: { url: HOOK, authMode: "hmac" } });
    expect(res.statusCode).toBe(201);
    const { behavior, secret } = res.json();
    expect(secret).toMatch(/^[0-9a-f]{64}$/);
    expect(behavior.webhook).toEqual({
      url: HOOK,
      authMode: "hmac",
      secretSet: true,
      previousSecretExpiresAt: null,
    });

    const list = await server.inject({ method: "GET", url: "/api/behaviors" });
    expect(list.body).not.toContain(secret);

    // the action the bot signs with holds that secret
    await server.inject({ method: "POST", url: `/api/behaviors/${behavior.id}/test` });
    const [action] = forward.mock.calls[0] as unknown as [{ secret: string }];
    expect(decryptSecret(action.secret)).toBe(secret);
  });

  it("appends a new trigger after every existing one", async () => {
    const first = await seedMessageTrigger({ sortOrder: 7 });
    const res = await create(dmTrigger);
    expect((await listed()).map((t) => t.id)).toEqual([first, res.json().behavior.id]);
  });

  it.each([
    ["an audience outside bot DMs", { surface: "guild", audienceKind: "user", audienceUserId: USER }, "audienceKind"],
    ["a guild on a bot DM trigger", { guildId: GUILD }, "guildId"],
    ["a channel without its guild", { surface: "guild", channelId: CHANNEL }, "channelId"],
    ["a user audience without the user", { audienceKind: "user" }, "audienceUserId"],
    ["a group audience carrying a user", { audienceKind: "group", audienceGroupName: "vip", audienceUserId: USER }, "audienceUserId"],
    ["ignoreBots off in bot DMs (bot authors never reach them)", { ignoreBots: false }, "ignoreBots"],
    ["an invalid regex", { patternKind: "regex", patternValue: "(" }, "patternValue"],
    ["a blank title", { title: "   " }, "title"],
    ["a plain-http public webhook", { webhook: { url: "http://203.0.113.10/hook" } }, "webhook.url"],
    ["an unknown field", { scope: "global" }, "scope"],
    ["a leaf-only field", { options: [] }, "options"],
    ["a non-snowflake guild", { surface: "guild", guildId: "123" }, "guildId"],
  ])("refuses %s", async (_what, change, field) => {
    const res = await create({ ...dmTrigger, ...change });
    expect(res.statusCode).toBe(400);
    expect(res.json().error).toMatchObject({ code: "validation_failed", field });
  });
});

describe("PATCH /api/behaviors/:id (message trigger)", () => {
  it("changes only the given fields", async () => {
    const id = (await create(dmTrigger)).json().behavior.id;
    const res = await patch(id, { patternValue: "!hi", stopOnMatch: true });
    expect(res.statusCode).toBe(200);
    expect(res.json().behavior).toMatchObject({
      title: "hello",
      patternValue: "!hi",
      stopOnMatch: true,
    });
  });

  it("checks the merged result, not just the patch", async () => {
    const id = (
      await create({ ...dmTrigger, audienceKind: "user", audienceUserId: USER })
    ).json().behavior.id;
    const res = await patch(id, { surface: "guild" });
    expect(res.statusCode).toBe(400);
    expect(res.json().error).toMatchObject({ code: "validation_failed", field: "audienceKind" });
  });

  it("moves a trigger from bot DMs to a guild with its audience reset", async () => {
    const id = (
      await create({ ...dmTrigger, audienceKind: "user", audienceUserId: USER })
    ).json().behavior.id;
    const res = await patch(id, {
      surface: "guild",
      guildId: GUILD,
      audienceKind: "all",
      audienceUserId: null,
    });
    expect(res.statusCode).toBe(200);
    expect(res.json().behavior).toMatchObject({ section: `guild:${GUILD}`, audienceKind: "all" });
  });

  it("issues a secret when auth is turned on, keeps it across modes, clears it when off", async () => {
    const id = (await create(dmTrigger)).json().behavior.id;

    const on = await patch(id, { webhook: { url: HOOK, authMode: "token" } });
    expect(on.statusCode).toBe(200);
    const secret = on.json().secret as string;
    expect(secret).toMatch(/^[0-9a-f]{64}$/);

    const switched = await patch(id, { webhook: { url: HOOK, authMode: "hmac" } });
    expect(switched.json()).not.toHaveProperty("secret");
    expect(switched.json().behavior.webhook).toMatchObject({ authMode: "hmac", secretSet: true });

    const off = await patch(id, { webhook: { url: HOOK, authMode: null } });
    expect(off.json().behavior.webhook).toEqual({
      url: HOOK,
      authMode: null,
      secretSet: false,
      previousSecretExpiresAt: null,
    });
  });

  it("refuses a stale write", async () => {
    const created = (await create(dmTrigger)).json().behavior;
    await patch(created.id, { title: "first" });
    const res = await patch(created.id, { title: "second", ifUpdatedAt: "2000-01-01T00:00:00.000Z" });
    expect(res.statusCode).toBe(409);
    expect(res.json().error).toMatchObject({ code: "validation_failed", field: "ifUpdatedAt" });
  });

  it("accepts a write based on the current version", async () => {
    const created = (await create(dmTrigger)).json().behavior;
    const res = await patch(created.id, { title: "next", ifUpdatedAt: created.updatedAt });
    expect(res.statusCode).toBe(200);
  });

  it("refuses an empty patch", async () => {
    const id = (await create(dmTrigger)).json().behavior.id;
    const res = await patch(id, {});
    expect(res.statusCode).toBe(400);
    expect(res.json().error.code).toBe("validation_failed");
  });

  it("an unknown id is not_found", async () => {
    const res = await patch(9999, { title: "x" });
    expect(res.statusCode).toBe(404);
    expect(res.json().error.code).toBe("not_found");
  });

  it("the system behavior is immutable", async () => {
    const id = await seedSystemLogin();
    const res = await patch(id, { enabled: false });
    expect(res.statusCode).toBe(409);
    expect(res.json().error.code).toBe("system_immutable");
  });
});

describe("DELETE /api/behaviors/:id (message trigger)", () => {
  it("removes the trigger", async () => {
    const id = (await create(dmTrigger)).json().behavior.id;
    const res = await server.inject({ method: "DELETE", url: `/api/behaviors/${id}` });
    expect(res.statusCode).toBe(204);
    expect(await listed()).toEqual([]);
  });

  it("refuses the system behavior", async () => {
    const id = await seedSystemLogin();
    const res = await server.inject({ method: "DELETE", url: `/api/behaviors/${id}` });
    expect(res.statusCode).toBe(409);
    expect(res.json().error.code).toBe("system_immutable");
  });

  it("an unknown id is not_found", async () => {
    const res = await server.inject({ method: "DELETE", url: "/api/behaviors/9999" });
    expect(res.statusCode).toBe(404);
  });
});

describe("audit", () => {
  it("records create, update and delete without the URL or the secret", async () => {
    const created = await create({ ...dmTrigger, webhook: { url: HOOK, authMode: "hmac" } });
    const { behavior, secret } = created.json();
    await patch(behavior.id, { patternValue: "!bye" });
    await server.inject({ method: "DELETE", url: `/api/behaviors/${behavior.id}` });

    const entries = await listAudit({ limit: 3 });
    expect(entries.map((e) => [e.action, e.target])).toEqual([
      ["behavior.delete", `behavior:${behavior.id}`],
      ["behavior.update", `behavior:${behavior.id}`],
      ["behavior.create", `behavior:${behavior.id}`],
    ]);
    expect(entries[1]!.context).toMatchObject({
      changed: { patternValue: { from: "!hello", to: "!bye" } },
    });
    const text = JSON.stringify(entries);
    expect(text).not.toContain(secret);
    expect(text).not.toContain("203.0.113.10");
    expect(entries[2]!.context).toMatchObject({
      webhook: { authMode: "hmac", secretSet: true, urlFingerprint: expect.stringMatching(/^[0-9a-f]{12}$/) },
    });
  });
});

describe("GET /api/behaviors/schema (#108)", () => {
  async function servedValidator() {
    const res = await server.inject({ method: "GET", url: "/api/behaviors/schema" });
    expect(res.statusCode).toBe(200);
    const { Ajv } = await import("ajv");
    return new Ajv({ strict: false }).compile(res.json().messageTrigger);
  }

  it("serves the schema POST /api/behaviors validates a message trigger with", async () => {
    const accepts = await servedValidator();
    const refused = [
      { ...dmTrigger, title: "x".repeat(101) },
      { ...dmTrigger, title: "   " },
      { ...dmTrigger, guildId: "12345" },
      { ...dmTrigger, patternValue: "" },
      { ...dmTrigger, webhook: { url: "" } },
    ];
    for (const payload of refused) {
      expect(accepts(payload)).toBe(false);
      expect((await create(payload)).statusCode).toBe(400);
    }
    expect(accepts(dmTrigger)).toBe(true);
    expect((await create(dmTrigger)).statusCode).toBe(201);
  });

  it("needs the behavior capability", async () => {
    const open = Fastify({ logger: false });
    open.addHook("onRequest", async (request) => {
      request.authUserId = "nobody";
      request.authCapabilities = new Set() as never;
    });
    await registerBehaviorRoutes(open);
    await open.ready();
    const res = await open.inject({ method: "GET", url: "/api/behaviors/schema" });
    expect(res.statusCode).toBe(403);
    await open.close();
  });
});
